{
  "probability": 0.22,
  "range_low": 0.18,
  "range_high": 0.28,
  "summary": [
    "Starting with a base-rate anchor near 0.44 for achieving a two-thirds majority under Hungary's electoral rules, as observed in 2010–2022 outcomes.",
    "Credible seat projections in early 2026 place totals for any bloc well below 133 seats, tempering the odds of a 2/3 majority.",
    "Divergent polls and ongoing questions about opposition unity introduce uncertainty, creating a tail risk but not a clear path to a supermajority.",
    "Calibrated posterior probability = 0.22, with an uncertainty range of 0.18–0.28 to reflect mixed signals and structural dynamics."
  ],
  "confidence": "low",
  "narrative": "Anchored on a historical base-rate for a 2/3 majority, current seat projections and poll divergence suggest substantial downside risk to a 133+ outcome. While structural rules and potential opposition unity could raise odds, the prevailing data indicate the supermajority is unlikely, yielding a posterior near 0.22 with wide enough uncertainty to accommodate change.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base-rate for achieving a two-thirds majority (133+ seats) in the Hungarian National Assembly since 1990; four of nine elections produced a 2/3 outcome, implying a base-rate around 0.44."
    },
    "factor_updates": [
      {
        "factor": "Structural electoral rules favor incumbents (districting, SMCs, electoral mathematics)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Historical patterns show the current system facilitates large seat gains for the governing bloc, supporting a higher ceiling for a 2/3 outcome."
      },
      {
        "factor": "Opposition consolidation potential (TISZA unification or broader cross-party coalition)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A united opposition could translate votes into more seats, increasing the chance of reaching 133+."
      },
      {
        "factor": "Poll momentum toward the opposition (credible surveys showing TISZA lead or narrowing gaps)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Surveys showing opposition gains raise the probability of higher seat shares if turnout follows suit."
      },
      {
        "factor": "Market expectations of regime change and policy signaling",
        "direction": "up",
        " magnitude": "weak",
        "rationale": "Financial signaling of possible regime change may nudge expectations upward in certain scenarios, but it's a peripheral driver for seat tallies."
      },
      {
        "factor": "Credible seat projections showing no near-2/3 path for any bloc",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Public projections placing majorities well below 133 strongly dampen the probability of a 2/3 outcome."
      },
      {
        "factor": "Historical base-rate constraint (2/3 achieved in 4 of 9 elections since 1990)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "While possible, 2/3 occurrences are relatively rare, imposing a non-negligible constraint on likelihood."
      },
      {
        "factor": "Persistent fragmentation within opposition reducing coherence",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Dispersed anti-incumbent votes limit consolidation of seats toward 133+."
      },
      {
        "factor": "Divergent polling signals and lack of consensus among pollsters",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "No single forecast shows a clear 133+ path; lack of consensus lowers confidence in a 2/3 outcome."
      }
    ],
    "synthesis_rationale": "Starting from a 0.44 anchor, the updates include strong upward pressure from structural rules and moderate upward pressure from potential opposition unity and polling momentum, but these are offset by strong downward pressure from credible seat projections and historical base-rate constraints, plus fragmentation and polling dispersion. The net calibrated posterior lands at 0.22 with a 0.18–0.28 range, reflecting balanced consideration of both upside and downside drivers and acknowledging substantial uncertainty in the current data environment."
  }
}

{
  "probability": 0.22,
  "range_low": 0.18,
  "range_high": 0.28,
  "summary": [
    "Posterior probability of any party or coalition achieving a constitutional two-thirds majority (133+ seats) in 2026 is 0.22, reflecting a relatively unlikely outcome given current data.",
    " Contemporary polls show a split landscape with no clear path to 133+ seats for any bloc, and credible seat projections place totals well below 133.",
    " Structural electoral rules in Hungary provide an incumbency advantage, which raises the ceiling but does not guarantee a 2/3 majority under current conditions.",
    " The uncertainty remains highly contingent on opposition unity and turnout dynamics; nevertheless, the net calibration leans toward sub-2/3 outcomes under the present evidence."
  ],
  "confidence": "medium",
  "narrative": "Starting from a historical base-rate and updating with current polls and seat projections, the balance of evidence tilts toward sub-2/3 outcomes. While structural rules provide upside, the combination of divergent polls and credible projections without a clear 133+ path keeps the odds around one in five.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base-rate: two-thirds majority has occurred in 4 of 9 Hungarian elections since 1990 (approximately 0.44), used as a baseline anchor for the reference class."
    },
    "factor_updates": [
      {
        "factor": "Structural electoral rules favor incumbents (districting, SMCs, electoral mathematics)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Historical patterns show the system magnifies seat gains for the governing side, raising the theoretical ceiling for a 2/3 majority."
      },
      {
        "factor": "Opposition consolidation potential (TISZA unification or broader cross-party coalition)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A united opposition could convert dispersed anti-incumbent votes into more seats, increasing 2/3 odds under favorable turnout and sequencing."
      },
      {
        "factor": "Poll momentum toward the opposition (credible surveys showing TISZA lead or narrowing gaps)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Several February 2026 polls show TISZA ahead or competitive, signaling momentum that could translate into more seats if turnout aligns."
      },
      {
        "factor": "Market expectations of regime change and policy signaling",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Financial signals (e.g., forint strengthening in regime-change scenarios) reflect expectations that a non-incumbent victory could occur, contributing modestly to the perceived plausibility of a 2/3 outcome."
      },
      {
        "factor": "Credible seat projections showing no near-2/3 path for any bloc",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Publicus/IDEA/Nézőpont projections place leading blocs well short of 133 seats, providing a substantial downward pressure on the probability of a 2/3 majority."
      },
      {
        "factor": "Historical base-rate constraint (2/3 achieved in 4 of 9 elections since 1990)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "The precedent that 2/3 is uncommon lowers the prior odds and reinforces caution about near-term 2/3 outcomes."
      },
      {
        "factor": "Persistent fragmentation within opposition reducing coherence",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Fragmentation can dilute anti-incumbent vote shares and impede reaching 133+ seats, especially if unified lists are not formed."
      },
      {
        "factor": "Divergent polling signals and lack of consensus among pollsters",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "No single projection points decisively to 133+ seats; cross-poll results create uncertainty that undermines a confident 2/3 forecast."
      }
    ],
    "synthesis_rationale": "The posterior of 0.22 emerges from balancing a strong downward pull from credible seat projections and historical base-rate constraints against modest upward pushes from potential opposition unity, polling momentum, and market signals. Given the weight of the downward factors and the lack of a convergent 133+ projection, the calibrated estimate sits at 0.22 with a modest uncertainty range.",
    "notes": "Calibrated to reflect a Bayesian-style update using the provided factors; ranges reflect uncertainty around coalition dynamics, turnout, and polling reliability."
  }
}

